-- P5 中文科 5CL2–5CL5 整批擴充：共新增 280 題（每單元由 10 題增至 80 題）
-- 可安全重複執行：以 node_id + question_text 跳過已存在題目；不刪除原有題目。

begin;

do $$
declare missing_codes text;
begin
  select string_agg(code, ', ' order by code) into missing_codes
  from (values ('5CL2'), ('5CL3'), ('5CL4'), ('5CL5')) wanted(code)
  where not exists (select 1 from public.curriculum_nodes n where n.code = wanted.code);
  if missing_codes is not null then
    raise exception '找不到課程單元：%', missing_codes;
  end if;
end $$;

create temporary table tmp_chinese_language_expansion (
  node_code text not null,
  category text not null,
  question_text text not null,
  options jsonb not null,
  correct_answer jsonb not null,
  explanation text not null,
  hint text not null,
  difficulty integer not null
) on commit drop;


do $$
declare bad_count integer;
begin
  select count(*) into bad_count
  from (values ('5CL2',70),('5CL3',70),('5CL4',70),('5CL5',70)) expected(code, qty)
  where (select count(*) from tmp_chinese_language_expansion t where t.node_code = expected.code) <> expected.qty;
  if bad_count > 0 then raise exception '增補題數檢查失敗。'; end if;
  if (select count(*) from tmp_chinese_language_expansion) <> 280 then raise exception '總題數不是 280 題。'; end if;
  if (select count(*) from tmp_chinese_language_expansion) <> (select count(*) from (select distinct node_code, question_text from tmp_chinese_language_expansion) d) then
    raise exception '增補題目中有重複題幹。';
  end if;
end $$;

select n.id, 'multiple_choice', t.question_text, t.options, t.difficulty, 'teacher', 'published'
from tmp_chinese_language_expansion t
join public.curriculum_nodes n on n.code = t.node_code
where not exists (
  select 1 from public.questions q where q.node_id = n.id and q.question_text = t.question_text
);

select q.id, t.correct_answer, t.explanation, t.hint
from tmp_chinese_language_expansion t
join public.curriculum_nodes n on n.code = t.node_code
join public.questions q on q.node_id = n.id and q.question_text = t.question_text
on conflict (question_id) do update set
  correct_answer = excluded.correct_answer,
  explanation = excluded.explanation,
  hint = excluded.hint;

commit;

select n.code, n.title_zh,
  count(q.id) filter (where q.status = 'published') as published_questions
from public.curriculum_nodes n
left join public.questions q on q.node_id = n.id
where n.code in ('5CL2','5CL3','5CL4','5CL5')
group by n.code, n.title_zh
order by n.code;
